/**
 * Atrium — Alpine bootstrap, shared stores and helpers.
 *
 * ── HOUSE RULE: NO ES6 TEMPLATE LITERALS IN THIS FOLDER ──────────────────────
 * CubeCart minifies skin JS with JSMin (includes/smarty/plugins/minify/JSmin.php,
 * Crockford 2002), which predates backticks and does not understand them.
 * Verified by execution against this tree's own copy:
 *
 *   backtick string containing an apostrophe
 *       -> throws JSMin_UnterminatedStringException (PHP fatal, white screen
 *          for every customer on every page)
 *   backtick string containing a URL
 *       -> truncated at "http:" — the // is read as a line comment
 *   backtick string containing a block comment
 *       -> the commented span is deleted from inside the string
 *   backtick string with a space after an interpolation
 *       -> the space is silently eaten, corrupting the output
 *
 * Everything else in ES2020 is safe: arrow functions, classes, ?., ??=, spread,
 * async/await, destructuring, object shorthand.
 *
 * This bundle currently bypasses {combine}, so it would survive — but the rule
 * is kept folder-wide so nobody has to remember which files are exempt.
 * ─────────────────────────────────────────────────────────────────────────────
 *
 * Load order is handled for us: every registration below happens inside an
 * 'alpine:init' listener, and Alpine core fires that event after all deferred
 * scripts have run. So this file works regardless of where it lands in the
 * <script> order, which matters because CubeCart's auto-loader sorts js/*.js as
 * strings (10.foo.js sorts before 2.foo.js).
 */

(function () {
    'use strict';

    /** CubeCart's CSRF token. Core injects a hidden input before every </form>
     *  (GUI::display()) and rejects POSTs without it
     *  (Sanitize::checkToken()). Read it from the DOM rather than
     *  templating it in, so AJAX calls always use a current value. */
    function ccToken() {
        var el = document.querySelector('input.cc_session_token, input[name="token"]');
        return el ? el.value : '';
    }

    /** Build a storefront URL with CubeCart's query-string conventions. */
    function ccUrl(params) {
        var base = (window.CC_ROOT_PATH || '') + 'index.php';
        var qs = new URLSearchParams(params || {}).toString();
        return qs ? base + '?' + qs : base;
    }

    /** POST a form to CubeCart and return the raw response text.
     *  Endpoints such as _g=ajaxadd return HTML fragments, not JSON — that is a
     *  documented plugin API (GUI::displaySideBasket()). Do not "improve"
     *  it into JSON. */
    async function ccPost(url, formData) {
        var res = await fetch(url, {
            method: 'POST',
            body: formData,
            credentials: 'same-origin',
            headers: { 'X-Requested-With': 'XMLHttpRequest' }
        });
        if (!res.ok) throw new Error('Request failed: ' + res.status);
        return res.text();
    }

    window.ccToken = ccToken;
    window.ccUrl = ccUrl;
    window.ccPost = ccPost;

    document.addEventListener('alpine:init', function () {
        var Alpine = window.Alpine;

        /* ── Stores ──────────────────────────────────────────────────────────
           Cross-fragment state lives here, never inside a component. The basket
           count appears in the header, the mobile drawer and the mini-basket at
           once; an AJAX call replaces only one of those fragments, so a
           component-local count would desync the other two. */
        Alpine.store('ui', {
            menuOpen: false,
            drawerOpen: false,
            searchOpen: false,

            closeAll: function () {
                this.menuOpen = false;
                this.drawerOpen = false;
                this.searchOpen = false;
            }
        });

        Alpine.store('basket', {
            /* Seeded from the server-rendered markup so the first paint is
               correct with JS disabled or slow. */
            count: 0,
            total: '',

            /** Adopt the authoritative values off a freshly injected fragment. */
            syncFrom: function (el) {
                if (!el) return;
                var c = el.getAttribute('data-basket-count');
                var t = el.getAttribute('data-basket-total');
                if (c !== null) this.count = parseInt(c, 10) || 0;
                if (t !== null) this.total = t;
            }
        });

        /* ── Components ──────────────────────────────────────────────────── */

        /** Dismissible flash message. Used by box.errors.php. */
        Alpine.data('ccAlert', function () {
            return {
                shown: true,
                dismiss: function () { this.shown = false; }
            };
        });

        /** Generic disclosure: dropdowns, accordions, the mobile nav.
         *  Closes on Escape and on click outside. */
        Alpine.data('ccDisclosure', function (initial) {
            return {
                open: initial === true,
                toggle: function () { this.open = !this.open; },
                close: function () { this.open = false; }
            };
        });

        /** Tab set. The active panel id must be declared here rather than
         *  bolted on with x-init: Alpine only makes properties reactive if they
         *  exist on the data object when the component initialises. */
        Alpine.data('ccTabs', function (initial) {
            return {
                tab: initial || '',
                select: function (id) { this.tab = id; },
                isActive: function (id) { return this.tab === id; }
            };
        });

        /** Off-canvas panel (mobile nav, mini-basket drawer).
         *  Locks body scroll while open and restores it on close — reference
         *  counted via a data attribute so two panels cannot fight over it. */
        Alpine.data('ccDrawer', function (storeKey) {
            return {
                get open() {
                    return Alpine.store('ui')[storeKey] === true;
                },
                set open(v) {
                    Alpine.store('ui')[storeKey] = v;
                },
                close: function () { this.open = false; },
                lock: function () {
                    var n = parseInt(document.body.dataset.ccLocks || '0', 10) + 1;
                    document.body.dataset.ccLocks = String(n);
                    document.body.style.overflow = 'hidden';
                },
                unlock: function () {
                    var n = Math.max(0, parseInt(document.body.dataset.ccLocks || '0', 10) - 1);
                    document.body.dataset.ccLocks = String(n);
                    if (n === 0) document.body.style.overflow = '';
                }
            };
        });
    });
})();

/* ---- js/src/11-search.js ---- */
/**
 * Atrium — search-as-you-type.
 *
 * HOUSE RULE: no ES6 template literals in this folder. See 00-boot.js.
 *
 * Endpoint contract, unchanged from foundation's 2.cubecart.js:
 *   GET ?_e=es&q=<term>&a=<amount>
 * returns a JSON array of {product_id, name, thumbnail}, or something that is
 * not an array when there are no matches. Only active when Elasticsearch is
 * enabled, which the template signals with the `es` class on the input —
 * exactly the flag foundation used.
 */

document.addEventListener('alpine:init', function () {
    window.Alpine.data('ccSearch', function () {
        return {
            term: '',
            results: [],
            open: false,
            searched: false,
            /* Mirrors data-image. The template needs it so it can reserve the
               thumbnail slot even when a product has no image — 308 of the
               indexed products carry no `thumbnail` field at all, and without a
               placeholder those rows lose their 40px leading box and the text
               jumps left, breaking the column. */
            showImages: false,
            _seq: 0,

            close: function () {
                this.open = false;
            },

            /** Escape user input before it is ever put back into the DOM. */
            _escape: function (s) {
                return String(s)
                    .replace(/&/g, '&amp;')
                    .replace(/</g, '&lt;')
                    .replace(/>/g, '&gt;')
                    .replace(/"/g, '&quot;');
            },

            /** Bold each search word inside the (already escaped) product name. */
            _highlight: function (name, term) {
                var safe = this._escape(name);
                var words = term.split(/\s+/).filter(function (w) {
                    return w && w !== '*';
                });
                words.forEach(function (w) {
                    // Escape regex metacharacters in the user's own term.
                    var pattern = w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                    safe = safe.replace(new RegExp('(' + pattern + ')', 'ig'), '<strong>$1</strong>');
                });
                return safe;
            },

            async go() {
                var input = this.$refs.input;
                // No Elasticsearch -> no live search. Plain form submit still works.
                if (!input || !input.classList.contains('es')) return;

                var term = this.term.trim();
                if (!term) {
                    this.results = [];
                    this.searched = false;
                    this.open = false;
                    return;
                }

                var amount = input.getAttribute('data-amount') || 15;
                var showImages = input.getAttribute('data-image') === 'true';
                this.showImages = showImages;

                // Guard against out-of-order responses: only the newest wins.
                var seq = ++this._seq;

                try {
                    var res = await fetch('?_e=es&q=' + encodeURIComponent(term) + '&a=' + encodeURIComponent(amount), {
                        credentials: 'same-origin'
                    });
                    var data = await res.json();
                    if (seq !== this._seq) return;

                    var self = this;
                    this.results = Array.isArray(data) ? data.map(function (p) {
                        return {
                            product_id: p.product_id,
                            name: p.name,
                            url: '?_a=product&product_id=' + encodeURIComponent(p.product_id),
                            thumbnail: showImages && p.thumbnail ? p.thumbnail : '',
                            highlighted: self._highlight(p.name, term)
                        };
                    }) : [];
                } catch (e) {
                    if (seq !== this._seq) return;
                    this.results = [];
                }

                this.searched = true;
                this.open = true;
            }
        };
    });
});

/* ---- js/src/12-basket.js ---- */
/**
 * Atrium — add to basket.
 *
 * HOUSE RULE: no ES6 template literals in this folder. See 00-boot.js.
 *
 * ENDPOINT CONTRACT (do not change — this is core behaviour, not skin behaviour):
 *   POST <form action> + "&_g=ajaxadd&t=<timestamp>"
 *   handled by the 'ajaxadd' case in Cubecart::loadPage() -> GUI::displaySideBasket()
 *
 *   Response is one of:
 *     "Redir:<url>"  -> the store is configured to jump to the basket
 *                       (config basket_jump_to, Cart::add())
 *     <html>         -> the rendered box.basket.php fragment, to be swapped
 *                       into #mini-basket
 *
 *   It returns HTML rather than JSON, and plugins hook
 *   class.gui.display_side_basket to modify that HTML. Do not "improve" this
 *   into a JSON API — it is a published extension point.
 *
 * The CSRF token is already inside the form: core injects a hidden input before
 * every </form> (GUI::display()), and FormData picks it up, so the
 * POST satisfies Sanitize::checkToken().
 */

document.addEventListener('alpine:init', function () {
    window.Alpine.data('ccAddToBasket', function () {
        return {
            busy: false,
            added: false,

            async submit(event) {
                var form = event.target;

                // Let the browser enforce required options (a required select
                // with no choice, a required text option left empty).
                if (!form.reportValidity()) return;

                event.preventDefault();
                if (this.busy) return;
                this.busy = true;

                var action = form.getAttribute('action') || window.location.href;
                action = action.replace(/\?.*/, '');
                var url = action + (action.indexOf('?') > -1 ? '&' : '?') +
                          '_g=ajaxadd&t=' + new Date().getTime();

                try {
                    var text = await window.ccPost(url, new FormData(form));

                    if (text.indexOf('Redir:') !== -1) {
                        window.location = text.split('Redir:')[1];
                        return;
                    }

                    // Swap the mini-basket. Alpine's MutationObserver
                    // initialises x-data on the inserted subtree automatically,
                    // so the replacement is live with no re-init call.
                    var host = document.getElementById('mini-basket');
                    if (host) {
                        host.outerHTML = text;
                        var fresh = document.getElementById('mini-basket');
                        if (fresh) window.Alpine.store('basket').syncFrom(fresh);
                    }

                    this.added = true;
                    var self = this;
                    setTimeout(function () { self.added = false; }, 2500);
                } catch (e) {
                    // Network failure: fall back to a normal form post rather
                    // than silently losing the customer's click.
                    form.submit();
                } finally {
                    this.busy = false;
                }
            }
        };
    });
});

/* ---- js/src/20-product.js ---- */
/**
 * Atrium — product page: option-driven price recalculation and image swapping.
 *
 * HOUSE RULE: no ES6 template literals in this folder. See 00-boot.js.
 *
 * ENDPOINT CONTRACT (core, not skin):
 *   GET <form action> + "&_g=ajax_price_format&price[0]=<n>[&price[1]=<n>]"
 *   handled by the 'ajax_price_format' case in Cubecart::loadPage(), which returns a JSON ARRAY
 *   of currency-formatted strings in the same order.
 *
 *   Prices must be formatted server-side: only PHP knows the store's currency,
 *   decimal places, tax mode and rounding. Never format money in JS.
 *
 * DOM CONTRACT (set by element.product.call_to_action.php):
 *   #ptp  data-price = price_to_pay      the price actually charged
 *   #fbp  data-price = full_base_price   the "was" price; present only on sale
 *
 * OPTION PRICING (element.product.options.php):
 *   [name^=productOptions] carry data-price and data-price-original.
 *   class="absolute" means the option REPLACES the base price rather than
 *   adding to it — subtract the base before adding the option's own price.
 */

document.addEventListener('alpine:init', function () {
    window.Alpine.data('ccProduct', function () {
        return {
            _seq: 0,

            init: function () {
                // Only meaningful when there is a price element AND options.
                if (!document.getElementById('ptp')) return;
                if (!this.$el.querySelector('[name^=productOptions]')) return;
                this.recalc();
            },

            /** Sum the selected options, then ask the server to format. */
            async recalc() {
                var ptpEl = document.getElementById('ptp');
                var fbpEl = document.getElementById('fbp');
                if (!ptpEl) return;

                var base = parseFloat(ptpEl.getAttribute('data-price'));
                var baseOriginal = fbpEl ? parseFloat(fbpEl.getAttribute('data-price')) : null;
                if (isNaN(base)) return;

                var delta = 0;
                var deltaOriginal = 0;
                var fields = this.$el.querySelectorAll('[name^=productOptions]');

                fields.forEach(function (el) {
                    var price, priceOriginal, absolute;

                    if (el.tagName === 'SELECT') {
                        var opt = el.options[el.selectedIndex];
                        if (!opt || !el.value) return;
                        price = parseFloat(opt.getAttribute('data-price'));
                        priceOriginal = parseFloat(opt.getAttribute('data-price-original'));
                        absolute = opt.classList.contains('absolute');
                    } else if (el.type === 'radio' || el.type === 'checkbox') {
                        if (!el.checked) return;
                        price = parseFloat(el.getAttribute('data-price'));
                        priceOriginal = parseFloat(el.getAttribute('data-price-original'));
                        absolute = el.classList.contains('absolute');
                    } else if (el.type === 'hidden') {
                        price = parseFloat(el.getAttribute('data-price'));
                        priceOriginal = parseFloat(el.getAttribute('data-price-original'));
                        absolute = el.classList.contains('absolute');
                    } else {
                        // text / textarea: only charged when the customer typed something
                        if (!el.value) return;
                        price = parseFloat(el.getAttribute('data-price'));
                        priceOriginal = parseFloat(el.getAttribute('data-price-original'));
                        absolute = el.classList.contains('absolute');
                    }

                    if (isNaN(price)) price = 0;
                    if (isNaN(priceOriginal)) priceOriginal = price;

                    if (absolute) {
                        delta -= base;
                        if (baseOriginal !== null) deltaOriginal -= baseOriginal;
                    }
                    delta += price;
                    deltaOriginal += priceOriginal;
                });

                var total = base + delta;
                var query = '_g=ajax_price_format&price[0]=' + encodeURIComponent(total);
                if (baseOriginal !== null) {
                    query += '&price[1]=' + encodeURIComponent(baseOriginal + deltaOriginal);
                }

                var action = (this.$el.getAttribute('action') || window.location.href);
                var url = action + (action.indexOf('?') > -1 ? '&' : '?') + query;

                var seq = ++this._seq;
                try {
                    var res = await fetch(url, { credentials: 'same-origin' });
                    var prices = await res.json();
                    if (seq !== this._seq) return;      // a newer change won
                    if (!Array.isArray(prices)) return;

                    ptpEl.innerHTML = prices[0];
                    if (fbpEl && prices.length > 1) {
                        fbpEl.innerHTML = prices[1];
                        // Hide the "was" price when the option choice has made
                        // it no cheaper than what is actually being charged.
                        var num = function (s) {
                            return parseFloat(String(s).replace(/[^0-9.-]/g, ''));
                        };
                        fbpEl.style.display = num(prices[0]) <= num(prices[1]) ? 'none' : '';
                    }
                } catch (e) {
                    // Leave the server-rendered price in place: a stale-but-real
                    // price is safer than a blank or a guess.
                }
            },

            /** Swap the main image when an option carries its own picture. */
            swapImage: function (event) {
                var el = event.target;
                var src = '';

                if (el.tagName === 'SELECT') {
                    var opt = el.options[el.selectedIndex];
                    src = opt ? opt.getAttribute('data-image') : '';
                } else if (el.type === 'radio' || el.type === 'checkbox') {
                    src = el.checked ? el.getAttribute('data-image') : '';
                } else {
                    src = el.getAttribute('data-image');
                }

                if (!src) return;
                var preview = document.getElementById('img-preview');
                if (preview) preview.src = src;
            },

            onOptionChange: function (event) {
                this.recalc();
                this.swapImage(event);
            }
        };
    });
});

