/**
 * Atrium — product image gallery and lightbox.
 *
 * HOUSE RULE: no ES6 template literals in this folder. See 00-boot.js.
 *
 * Replaces foundation's Clearing (Foundation 5) lightbox and its hover-swap
 * handler. #img-preview is a contract: 20-product.js swaps that element's src
 * when a product option carries its own image.
 */

document.addEventListener('alpine:init', function () {
    window.Alpine.data('ccGallery', function (initialFull) {
        return {
            full: initialFull || '',   // full-size src for the lightbox
            open: false,

            /** Show a thumbnail's larger version in the main preview. */
            show: function (medium, full) {
                var preview = document.getElementById('img-preview');
                if (preview && medium) preview.src = medium;
                if (full) this.full = full;
            },

            /** Open the lightbox on whatever is currently previewed. */
            enlarge: function () {
                var preview = document.getElementById('img-preview');
                if (!this.full && preview) this.full = preview.src;
                this.open = true;
            },

            close: function () {
                this.open = false;
            }
        };
    });
});

/* ---- js/src/22-stars.js ---- */
/**
 * Atrium — star rating chooser for the review form.
 *
 * HOUSE RULE: no ES6 template literals in this folder. See 00-boot.js.
 *
 * The five radios in element.product_reviews.php remain the actual control —
 * this only paints them. They are hidden with .cc-sr-only, which keeps them in
 * the tab order, so the native radio group still provides:
 *   - arrow-key selection within the group
 *   - a single tab stop
 *   - the value core reads from $_POST['rating']
 * Nothing here handles keys; doing so would fight the browser.
 *
 * `hover` is a transient preview and `value` is the committed choice. Fill is
 * `i <= (hover || value)`, so leaving the row falls back to what is actually
 * selected rather than emptying the stars.
 */
document.addEventListener('alpine:init', function () {
    window.Alpine.data('ccStarRating', function () {
        return {
            value: 0,
            hover: 0,

            init: function () {
                // Core pre-checks a radio when the form is redisplayed after a
                // failed post ($RATING_STARS[].checked), so read the truth from
                // the DOM instead of threading it through the template.
                var checked = this.$el.querySelector('input[name="rating"]:checked');
                if (checked) this.value = parseInt(checked.value, 10) || 0;

                // Keep in step if anything else moves the selection — arrow
                // keys fire change on the radio, and the validator may reset it.
                var self = this;
                this.$el.addEventListener('change', function (e) {
                    if (e.target && e.target.name === 'rating') {
                        self.value = parseInt(e.target.value, 10) || 0;
                    }
                });
            }
        };
    });
});

/* ---- js/src/23-hero.js ---- */
/**
 * Atrium — controls for the homepage hero banners.
 *
 * HOUSE RULE: no ES6 template literals in this folder. See 00-boot.js.
 *
 * The .cc-hero markup arrives inside the merchant's homepage DOCUMENT (seeded
 * by the installer from the default_doc_content_welcome language string), so
 * the skin cannot template controls into it. This component attaches to a
 * wrapper in content.homepage.php, finds the .cc-hero scroller inside the
 * injected HTML, and drives it.
 *
 * The scroller is CSS scroll-snap and works on its own — swipe on touch,
 * shift+wheel on desktop. What it lacks is any SIGNAL that more banners exist,
 * because the scrollbar is hidden: on a 1400px desktop that left 3003px of
 * banners in a 993px window with nothing to click. These controls are that
 * signal, not the scrolling mechanism.
 *
 * DELIBERATELY NOT AUTO-ROTATING. Auto-advancing heroes engage poorly (clicks
 * concentrate on the first slide), and anything that moves for more than five
 * seconds needs a pause control to satisfy WCAG 2.2.2 plus a
 * prefers-reduced-motion path. Manual controls avoid all of it.
 */
document.addEventListener('alpine:init', function () {
    window.Alpine.data('ccHero', function () {
        return {
            count: 0,
            index: 0,
            _el: null,

            init: function () {
                this._el = this.$el.querySelector('.cc-hero');
                if (!this._el) return;
                this.count = this._el.children.length;
                if (this.count < 2) return;

                var self = this;
                var ticking = false;
                this._el.addEventListener('scroll', function () {
                    if (ticking) return;
                    ticking = true;
                    window.requestAnimationFrame(function () {
                        var w = self._el.clientWidth || 1;
                        self.index = Math.round(self._el.scrollLeft / w);
                        ticking = false;
                    });
                }, { passive: true });
            },

            go: function (i) {
                if (!this._el) return;
                var n = Math.max(0, Math.min(this.count - 1, i));
                this._el.scrollTo({ left: n * this._el.clientWidth, behavior: 'smooth' });
                this.index = n;
            },
            next: function () { this.go(this.index + 1); },
            prev: function () { this.go(this.index - 1); }
        };
    });
});

