/**
 * Atrium — checkout behaviour.
 *
 * HOUSE RULE: no ES6 template literals in this folder. See 00-boot.js.
 *
 * Replaces the checkout half of foundation's 2.cubecart.js. Every DOM id and
 * field name below is a CORE CONTRACT read by PHP — see the comments in
 * content.checkout.php and content.checkout.confirm.php.
 *
 * COUNTRY -> STATE DEPENDENCY
 *   window.county_list is emitted by the template from $STATE_JSON: an object
 *   keyed by country numcode whose values are arrays of {id, name}.
 *   Each country <select> carries rel="<id of the state field>", and the
 *   selected <option> carries data-status:
 *       1 = state REQUIRED   2 = state optional   3 = state HIDDEN
 *   The wrapper to show/hide is "<target id>_wrapper".
 *
 *   Foundation replaced the state <input> with a <select> (and back) by
 *   destroying and rebuilding the element. That loses any value the customer
 *   already typed and any listener bound to it. Atrium keeps BOTH elements in
 *   the DOM and toggles which one is enabled, so the posted field name is
 *   always right and nothing is rebuilt.
 */

document.addEventListener('alpine:init', function () {
    window.Alpine.data('ccCheckout', function () {
        return {
            deliveryIsBilling: true,
            showRegister: false,
            mode: 'register',        // 'register' | 'login' — guest checkout only
            estimateOpen: false,

            init: function () {
                var dib = document.getElementById('delivery_is_billing');
                if (dib) {
                    this.deliveryIsBilling = dib.type === 'hidden' ? true : dib.checked;
                }
                var reg = document.getElementById('show-reg');
                if (reg) this.showRegister = reg.checked;

                // If the server came back with validation errors, the customer
                // was mid-edit — open the address form rather than hiding it.
                if (document.querySelector('.cc-alert-error')) {
                    this.mode = 'register';
                }

                // Deep links used by the login/register toggle.
                if (window.location.hash === '#login') this.mode = 'login';
                if (window.location.hash === '#register') this.mode = 'register';

                this.syncAuthFields();
                this.$nextTick(this.initCountries.bind(this));
            },

            /* ---- guest login / register ------------------------------------
               The login and register field sets live in ONE form, so both would
               post together. Foundation disabled the inactive set so the server
               only ever sees one. Same approach here — disabled fields are not
               submitted and are skipped by validation. */
            setMode: function (m) {
                this.mode = m;
                this.syncAuthFields();
            },

            syncAuthFields: function () {
                var login = this.mode === 'login';
                ['login-username', 'login-password', 'checkout_login_btn'].forEach(function (id) {
                    var el = document.getElementById(id);
                    if (el) el.disabled = !login;
                });
                var pw = document.getElementById('reg_password');
                var pc = document.getElementById('reg_passconf');
                if (pw) pw.disabled = login;
                if (pc) pc.disabled = login;
            },

            /* ---- create-an-account toggle ---------------------------------- */
            toggleRegister: function (event) {
                this.showRegister = event.target.checked;
                var pw = document.getElementById('reg_password');
                var pc = document.getElementById('reg_passconf');
                // required must track visibility or the browser blocks submit on
                // a field the customer cannot see.
                if (pw) pw.required = this.showRegister;
                if (pc) pc.required = this.showRegister;
            },

            /* ---- proceed ---------------------------------------------------
               Core distinguishes "update the basket" from "go to the next step"
               by the presence of a `proceed` field. The button is name="proceed"
               so a plain submit already carries it; this only adds it when the
               submit came from somewhere else. */
            proceed: function (event) {
                var form = document.getElementById('checkout_form');
                if (!form) return;

                // ⚠ Look for a HIDDEN input specifically. The earlier version
                // tested [name="proceed"], which ALWAYS matched — the submit
                // button itself is name="proceed" — so the compensator never
                // ran. Under invisible captcha (mode 3) grecaptcha submits the
                // form programmatically, and a programmatic submit does not
                // contribute the clicked button's name/value, so `proceed`
                // never posted and checkout silently never advanced.
                if (!form.querySelector('input[type="hidden"][name="proceed"]')) {
                    var i = document.createElement('input');
                    i.type = 'hidden';
                    i.name = 'proceed';
                    i.value = '1';
                    i.dataset.ccProceed = '1';
                    form.appendChild(i);
                }
            },

            /** Remove the compensator again — "Update basket" must NOT carry
             *  `proceed`, or updating a quantity would jump the customer to the
             *  next checkout step. */
            clearProceed: function () {
                var form = document.getElementById('checkout_form');
                if (!form) return;
                var i = form.querySelector('input[data-cc-proceed]');
                if (i) i.remove();
            },

            /* ---- country -> state ------------------------------------------
               Delegated to the page-level initialiser at the bottom of this
               file so the address book gets it too — that page has no
               ccCheckout component. */
            initCountries: function () {
                window.ccInitCountryState();
            },

            _unusedApplyState: function (sel) {
                if (typeof window.county_list !== 'object' || !window.county_list) return;

                var targetId = (sel.getAttribute('rel') && sel.id !== 'country-list')
                    ? sel.getAttribute('rel')
                    : 'state-list';

                var input   = document.getElementById(targetId);
                var select  = document.getElementById(targetId + '_select');
                var wrapper = document.getElementById(targetId + '_wrapper');
                if (!input) return;

                var opt = sel.options[sel.selectedIndex];
                var status = opt ? opt.getAttribute('data-status') : '2';
                var list = window.county_list[sel.value];
                var hasList = Array.isArray(list) && list.length > 0;

                // Show / hide / require, per the country's zone status.
                var hidden = status === '3';
                if (wrapper) wrapper.style.display = hidden ? 'none' : '';

                if (hasList) {
                    // Populate the paired <select> and use it instead of the text input.
                    if (select) {
                        var current = (input.value || select.value || '').toLowerCase();
                        select.innerHTML = '';
                        var blank = document.createElement('option');
                        blank.value = '';
                        blank.textContent = sel.getAttribute('title') || '';
                        select.appendChild(blank);
                        list.forEach(function (row) {
                            var o = document.createElement('option');
                            o.value = row.id > 0 ? row.id : '';
                            o.textContent = row.name;
                            if (current && (String(row.name).toLowerCase() === current || String(row.id) === current)) {
                                o.selected = true;
                            }
                            select.appendChild(o);
                        });
                        // Only ONE of the pair may be enabled: they share a name,
                        // and two enabled fields would post two values.
                        select.disabled = hidden;
                        select.required = !hidden && status === '1';
                        select.hidden = false;
                        input.disabled = true;
                        input.hidden = true;
                    }
                } else {
                    if (select) {
                        select.disabled = true;
                        select.hidden = true;
                        select.required = false;
                    }
                    input.disabled = hidden;
                    input.hidden = false;
                    input.required = !hidden && status === '1';
                }
            },

            /* ---- shipping estimate panel ----------------------------------- */
            toggleEstimate: function () {
                this.estimateOpen = !this.estimateOpen;
            }
        };
    });

    /** Basket line quantity stepper. Reveals the update button once a value
     *  actually differs from what the server currently holds. */
    window.Alpine.data('ccBasketLine', function (initial) {
        return {
            qty: parseInt(initial, 10) || 0,
            original: parseInt(initial, 10) || 0,

            get changed() {
                return this.qty !== this.original;
            },

            step: function (delta) {
                var next = this.qty + delta;
                if (next < 0 || next > 999) return;
                this.qty = next;
            }
        };
    });
});

/**
 * Gift certificate form: the recipient email field only applies to email
 * delivery. Kept out of the main ccCheckout component because this page has no
 * basket, no addresses and no gateways — nothing else in ccCheckout applies.
 */
document.addEventListener('alpine:init', function () {
    window.Alpine.data('ccGiftCertificate', function (initial) {
        return { method: initial || 'e' };
    });
});


/* ---------------------------------------------------------------------------
 * Country -> state, as a PAGE-LEVEL behaviour rather than a component method.
 *
 * Three pages need it — checkout, the shipping estimator and the address book —
 * and only checkout has a ccCheckout component. Binding it to the DOM instead
 * of to a component means a page just has to render the right markup:
 *
 *   <select class="country-list" rel="<state field id>">   options carry data-status
 *   <input  id="<state field id>"        name="x[state]">
 *   <select id="<state field id>_select" name="x[state]" hidden disabled>
 *   wrapper id="<state field id>_wrapper"
 *
 * data-status on the selected option: 1 = required, 2 = optional, 3 = hidden.
 * window.county_list maps country numcode -> [{id, name}].
 *
 * Input and select share a name and exactly ONE is ever enabled — a disabled
 * control is not submitted, so the posted value is unambiguous. Foundation
 * destroyed and rebuilt the element instead, losing anything already typed.
 * ------------------------------------------------------------------------- */
window.ccApplyCountryState = function (sel) {
    if (typeof window.county_list !== 'object' || !window.county_list) return;

    var targetId = (sel.getAttribute('rel') && sel.id !== 'country-list')
        ? sel.getAttribute('rel')
        : (sel.getAttribute('rel') || 'state-list');

    var input   = document.getElementById(targetId);
    var select  = document.getElementById(targetId + '_select');
    var wrapper = document.getElementById(targetId + '_wrapper');
    if (!input) return;

    var opt     = sel.options[sel.selectedIndex];
    var status  = opt ? opt.getAttribute('data-status') : '2';
    var list    = window.county_list[sel.value];
    var hasList = Array.isArray(list) && list.length > 0;
    var hidden  = status === '3';

    if (wrapper) wrapper.style.display = hidden ? 'none' : '';

    if (hasList && select) {
        var current = (input.value || select.value || '').toLowerCase();
        select.innerHTML = '';
        var blank = document.createElement('option');
        blank.value = '';
        blank.textContent = sel.getAttribute('title') || '';
        select.appendChild(blank);
        list.forEach(function (row) {
            var o = document.createElement('option');
            o.value = row.id > 0 ? row.id : '';
            o.textContent = row.name;
            if (current && (String(row.name).toLowerCase() === current || String(row.id) === current)) {
                o.selected = true;
            }
            select.appendChild(o);
        });
        select.disabled = hidden;
        select.required = !hidden && status === '1';
        select.hidden   = false;
        input.disabled  = true;
        input.hidden    = true;
    } else {
        if (select) {
            select.disabled = true;
            select.hidden   = true;
            select.required = false;
        }
        input.disabled = hidden;
        input.hidden   = false;
        input.required = !hidden && status === '1';
    }
};

window.ccInitCountryState = function () {
    document.querySelectorAll('select.country-list, select#country-list').forEach(function (sel) {
        if (sel.dataset.ccBound) return;      // idempotent: safe to call twice
        sel.dataset.ccBound = '1';
        window.ccApplyCountryState(sel);
        sel.addEventListener('change', function () { window.ccApplyCountryState(sel); });
    });
};

document.addEventListener('DOMContentLoaded', function () {
    window.ccInitCountryState();
});

/* ---- js/src/50-validate.js ---- */
/**
 * Atrium — client-side form validation.
 *
 * HOUSE RULE: no ES6 template literals in this folder. See 00-boot.js.
 *
 * WHAT THIS IS FOR
 * A UX layer only. Every rule here is also enforced server-side, and this file
 * never decides whether data is acceptable — it only tells the customer sooner.
 * Nothing here may be relied on for correctness or security.
 *
 * WHY NOT jQuery VALIDATE (what Foundation uses)
 * Foundation loads jquery.validate.js plus a 409-line rules file. Atrium ships
 * jQuery only as a compatibility shim for third-party plugins (see README) —
 * no skin code uses it, and adding a ~50KB jQuery plugin for this would undo
 * that. The markup already carries the constraint attributes (121 `required`,
 * 14 type=email, 7 type=tel, 31 maxlength), so the browser can do most of the
 * work and this file only supplies what the platform cannot:
 *
 *   - cross-field equality      passconf === password, emailconf === email
 *   - remote uniqueness         "that email already has an account"
 *   - message text              translated, from the store's language pack
 *   - presentation              inline messages instead of browser bubbles,
 *                               which are unstyleable and untranslatable
 *
 * NOVALIDATE IS SET FROM JS, DELIBERATELY
 * The form keeps native validation in the markup; init() adds `novalidate`
 * only once this script is running. With JS off or broken the browser still
 * blocks an empty required field, instead of the form silently losing its
 * only client-side check.
 *
 * MESSAGES
 * Read once from the JSON blob emitted by element.validation_messages.php.
 * Per-field override with data-msg-<rule>, e.g. data-msg-required="...".
 * Falls back to the browser's own localised validationMessage.
 *
 * WHY THIS IS NOT AN Alpine.data() COMPONENT
 * Alpine permits ONE x-data per element, and two forms already have their own
 * (box.newsletter.php uses ccNewsletter, content.certificates.php uses
 * ccGiftCertificate). A component here would collide with those and could not
 * be added to a plugin's form at all. Instead every form carrying
 * data-cc-validate is wired on load, and the instance is parked on the element
 * as form._ccValidator. That also means validation keeps working if Alpine
 * itself fails to load.
 *
 * ENDPOINT CONTRACT (core, not skin) — Cubecart::loadPage() 'ajax_email' case:
 *   POST ?_g=ajax_email            body: email=<addr>      (account lookup)
 *   POST ?_g=ajax_email&source=newsletter  body: subscribe=<addr>
 *   -> {"result":true|false,"token":"..."} when config.csrf=1, else bare true/false
 *   result TRUE  = address is FREE (no account / not subscribed)
 *   result FALSE = already taken
 * The token in the response is the SAME session token, not a rotated one
 * (Session::getToken() only regenerates when absent), so there is nothing to
 * write back into the form.
 */

(function () {
    'use strict';

    /* Message catalogue, parsed once. */
    var MESSAGES = (function () {
        var el = document.getElementById('cc-validation-messages');
        if (!el) return {};
        try { return JSON.parse(el.textContent || '{}'); } catch (e) { return {}; }
    })();

    /* Remote answers are cached per address so retyping the same value does
       not re-hit the server on every blur. */
    var remoteCache = {};

    function messageFor(field, rule) {
        var attr = field.getAttribute('data-msg-' + rule);
        if (attr) return attr;
        if (MESSAGES[rule]) return MESSAGES[rule];
        return field.validationMessage || 'Invalid';
    }

    /** Which built-in constraint failed, as a rule name we have a message for. */
    function nativeRule(field) {
        var v = field.validity;
        if (v.valid) return null;
        if (v.valueMissing) return 'required';
        if (v.typeMismatch) return field.type === 'email' ? 'email' : 'invalid';
        if (v.tooShort) return 'minlength';
        if (v.tooLong) return 'maxlength';
        if (v.patternMismatch) return field.type === 'tel' ? 'phone' : 'invalid';
        if (v.rangeUnderflow || v.rangeOverflow || v.stepMismatch) return 'invalid';
        return 'invalid';
    }

    /** Wire one form. Idempotent — a second call on the same form is a no-op. */
    function createValidator(form) {
        if (form._ccValidator) return form._ccValidator;

        var api = {
            $el: form,
            /* fieldName -> message. Only used to drive the DOM; the DOM is the
               source of truth for validity so a plugin that injects a field
               mid-life is picked up without re-initialising anything. */
            errors: {},
            busy: false,

            /* STICKY once validation has passed, and cleared only when the
               customer edits something. It must NOT be consumed by the first
               handler that sees it: the click and submit handlers both fire
               for one interaction, so a consume-on-read flag made the second
               handler re-enter and, on a .g-recaptcha submit button, loop
               forever (click -> submit -> captcha.click() -> click -> ...).
               That locked the renderer on the basket page. */
            _verified: false,

            init: function () {
                var form = this.$el;
                // Only now that JS is confirmed running. See header.
                form.setAttribute('novalidate', 'novalidate');

                var self = this;

                /* ── Submit interception ──────────────────────────────────────
                   MUST be a capture-phase CLICK, not the submit event.

                   Invisible reCAPTCHA (content.recaptcha.head.php, config
                   recaptcha=3) binds its own click handler to each
                   .g-recaptcha button and, once it has a token, submits with
                   form.submit(). form.submit() does NOT dispatch a submit
                   event — so a @submit handler never runs on registration,
                   checkout or the newsletter, i.e. precisely the forms where
                   validation matters most. Capturing the click lets us run
                   first and stopPropagation() before grecaptcha ever sees it.

                   Validation is async (remote email lookup), so we cannot
                   decide inline: cancel the click, validate, then replay it. */
                form.addEventListener('click', function (e) {
                    var btn = e.target.closest('button, input[type="submit"], input[type="image"]');
                    if (!btn || !form.contains(btn)) return;
                    var type = (btn.getAttribute('type') || 'submit').toLowerCase();
                    if (type !== 'submit' && type !== 'image') return;

                    // Secondary actions (update basket, fetch shipping rates,
                    // apply coupon) must not require the whole form to be
                    // valid. formnovalidate is the standard opt-out.
                    if (btn.hasAttribute('formnovalidate')) return;

                    if (self._verified) return;   // already passed; let it run

                    e.preventDefault();
                    e.stopPropagation();          // keep grecaptcha out until we pass
                    self.validateAll().then(function (ok) {
                        if (!ok) return;
                        self._verified = true;
                        btn.click();              // now grecaptcha (or the browser) proceeds
                    });
                }, true);

                /* Enter-key submits dispatch a real submit event and never
                   touch the button, so they bypass the handler above. */
                form.addEventListener('submit', function (e) {
                    /* Secondary actions opt out of validation AND of any
                       rerouting. formnovalidate only tells the BROWSER to skip
                       its own checks — it does not stop this listener, so
                       without this test "Update basket" was swallowed here:
                       validation passed, and the submission was then replayed
                       through the .g-recaptcha checkout button, which posts
                       `proceed` instead of `update`. The basket never updated. */
                    if (e.submitter && e.submitter.hasAttribute('formnovalidate')) return;

                    if (self._verified) return;
                    e.preventDefault();
                    var submitter = e.submitter;
                    self.validateAll().then(function (ok) {
                        if (!ok) return;
                        self._verified = true;
                        /* Replay the ACTUAL button so its name/value posts —
                           HTMLFormElement.submit() contributes neither, which is
                           the same trap the `proceed` compensator exists for. */
                        if (submitter) { submitter.click(); return; }
                        // If the form is reCAPTCHA-protected, go through its
                        // button so a token is still minted; submitting the
                        // form directly would post without one and be rejected.
                        var captcha = form.querySelector('.g-recaptcha');
                        if (captcha) { captcha.click(); return; }
                        HTMLFormElement.prototype.submit.call(form);
                    });
                });

                form.addEventListener('blur', function (e) {
                    if (self._isField(e.target)) self.checkField(e.target);
                }, true);

                // Clear a message as soon as the customer fixes the field, but
                // never introduce one mid-typing — that is hostile on a field
                // being filled in for the first time.
                form.addEventListener('input', function (e) {
                    if (self._isField(e.target) && self._errorEl(e.target)) {
                        self.checkField(e.target);
                    }
                });
                form.addEventListener('change', function (e) {
                    if (self._isField(e.target)) self.checkField(e.target);
                });

                /* Editing after a successful pass must force a re-check,
                   otherwise the sticky flag would wave through a form the
                   customer has since broken. */
                ['input', 'change'].forEach(function (evt) {
                    form.addEventListener(evt, function () { self._verified = false; }, true);
                });
            },

            _isField: function (el) {
                if (!el || !el.name) return false;
                var t = (el.tagName || '').toUpperCase();
                if (t !== 'INPUT' && t !== 'SELECT' && t !== 'TEXTAREA') return false;
                return el.type !== 'hidden' && el.type !== 'submit' && el.type !== 'button';
            },

            /* Every validatable control in the form, in DOM order.

               A radio GROUP is one field, not N. Every radio sharing a name
               reports valueMissing when none is checked, so without this the
               5-star rating group emitted five identical "No star rating was
               specified." messages. Keep only the first of each group. */
            _fields: function () {
                var self = this;
                var seen = {};
                return Array.prototype.filter.call(
                    this.$el.querySelectorAll('input, select, textarea'),
                    function (el) {
                        if (!self._isField(el)) return false;
                        if (el.type === 'radio') {
                            if (seen[el.name]) return false;
                            seen[el.name] = true;
                        }
                        return true;
                    }
                );
            },

            /* Where a message for this field should live.

               For a checkbox/radio the control and its <label> are usually
               flex SIBLINGS (e.g. terms_agree lives in
               <div class="flex items-start gap-2"><input><label></div>), so
               inserting after the input puts the message BETWEEN the box and
               its text, laid out inline by the flex parent. Anchor to the row
               instead so the message sits underneath it.

               Any field can opt out of the guesswork with a [data-field]
               wrapper, which always wins. */
            _anchor: function (field) {
                var explicit = field.closest('[data-field]');
                if (explicit) return explicit;

                if (field.type === 'radio') {
                    // The whole group gets one message, so anchor it after the
                    // group container rather than after any single radio.
                    var group = field.closest('fieldset');
                    if (group) return group;
                }
                if (field.type === 'radio' || field.type === 'checkbox') {
                    var wrapped = field.closest('label');
                    if (wrapped) return wrapped;
                    var row = field.parentElement;
                    if (row) {
                        // Only treat the parent as the row if it actually holds
                        // the label too; otherwise we would skip too far up.
                        var lbl = field.id
                            ? row.querySelector('label[for="' + CSS.escape(field.id) + '"]')
                            : row.querySelector('label');
                        if (lbl) return row;
                    }
                    return row || field;
                }
                return field;
            },

            _errorId: function (field) {
                // Radios key off the group NAME so the whole group shares a
                // single message element instead of one per radio.
                var key = (field.type === 'radio') ? field.name : (field.id || field.name);
                return 'ccerr-' + key.replace(/[^a-zA-Z0-9_-]/g, '_');
            },

            _errorEl: function (field) {
                return this.$el.querySelector('#' + CSS.escape(this._errorId(field)));
            },

            showError: function (field, message) {
                var id = this._errorId(field);
                var el = this._errorEl(field);
                if (!el) {
                    el = document.createElement('p');
                    el.id = id;
                    el.className = 'cc-field-error';
                    // Announced without stealing focus.
                    el.setAttribute('role', 'alert');
                    var anchor = this._anchor(field);
                    anchor.parentNode.insertBefore(el, anchor.nextSibling);
                }
                el.textContent = message;
                this._groupMembers(field).forEach(function (m) {
                    m.setAttribute('aria-invalid', 'true');
                    m.setAttribute('aria-describedby', id);
                });
                this.errors[field.name] = message;
            },

            clearError: function (field) {
                var el = this._errorEl(field);
                if (el && el.parentNode) el.parentNode.removeChild(el);
                var id = this._errorId(field);
                this._groupMembers(field).forEach(function (m) {
                    m.removeAttribute('aria-invalid');
                    if (m.getAttribute('aria-describedby') === id) {
                        m.removeAttribute('aria-describedby');
                    }
                });
                delete this.errors[field.name];
            },

            /** The field itself, or every radio sharing its name. */
            _groupMembers: function (field) {
                if (field.type !== 'radio' || !field.name) return [field];
                return Array.prototype.slice.call(
                    this.$el.querySelectorAll('input[type="radio"][name="' + CSS.escape(field.name) + '"]')
                );
            },

            /**
             * Synchronous rules only. Returns true when the field passes.
             * Remote checks are deliberately excluded so blur feedback is
             * instant; they run in checkRemote() / validateAll().
             */
            checkField: function (field) {
                if (field.disabled || field.type === 'hidden') { this.clearError(field); return true; }

                if (!field.checkValidity()) {
                    var rule = nativeRule(field);
                    this.showError(field, messageFor(field, rule));
                    return false;
                }

                // Cross-field equality: data-match points at another control.
                var matchSel = field.getAttribute('data-match');
                if (matchSel) {
                    var other = this.$el.querySelector(matchSel);
                    if (other && other.value !== field.value) {
                        this.showError(field, messageFor(field, 'match'));
                        return false;
                    }
                }

                this.clearError(field);
                return true;
            },

            /**
             * Remote uniqueness check. data-remote="email" | "newsletter".
             * Only runs on an otherwise-valid, non-empty field.
             */
            checkRemote: async function (field) {
                var kind = field.getAttribute('data-remote');
                if (!kind || !field.value || !field.checkValidity()) return true;

                var key = kind + '|' + field.value.toLowerCase();
                if (Object.prototype.hasOwnProperty.call(remoteCache, key)) {
                    if (remoteCache[key]) { return true; }
                    this.showError(field, messageFor(field, kind === 'newsletter' ? 'subscribed' : 'emailInUse'));
                    return false;
                }

                var body = new FormData();
                var url = (this.$el.getAttribute('action') || window.location.href).replace(/\?.*/, '');
                url += '?_g=ajax_email' + (kind === 'newsletter' ? '&source=newsletter' : '');
                body.append(kind === 'newsletter' ? 'subscribe' : 'email', field.value);
                var token = window.ccToken();
                if (token) body.append('token', token);

                try {
                    var text = await window.ccPost(url, body);
                    var data = JSON.parse(text);
                    // Bare true/false when config.csrf is off; object when on.
                    var free = (data === true) || (data && data.result === true);
                    remoteCache[key] = free;
                    if (free) return true;
                    this.showError(field, messageFor(field, kind === 'newsletter' ? 'subscribed' : 'emailInUse'));
                    return false;
                } catch (e) {
                    // Never block submission on a failed availability check —
                    // the server revalidates and is the authority.
                    return true;
                }
            },

            /** Full pass. Returns true when the form may be submitted. */
            validateAll: async function () {
                var fields = this._fields();
                var ok = true;
                var i;

                for (i = 0; i < fields.length; i++) {
                    if (!this.checkField(fields[i])) ok = false;
                }

                if (ok) {
                    var remotes = fields.filter(function (f) { return f.getAttribute('data-remote'); });
                    for (i = 0; i < remotes.length; i++) {
                        if (!(await this.checkRemote(remotes[i]))) ok = false;
                    }
                }

                if (!ok) {
                    var first = this.$el.querySelector('[aria-invalid="true"]');
                    if (first) {
                        first.focus({ preventScroll: true });
                        first.scrollIntoView({ block: 'center', behavior: 'smooth' });
                    }
                }
                return ok;
            }
        };

        form._ccValidator = api;
        api.init();
        return api;
    }

    function attachAll(root) {
        var scope = root || document;
        var forms = scope.querySelectorAll ? scope.querySelectorAll('form[data-cc-validate]') : [];
        Array.prototype.forEach.call(forms, createValidator);
    }

    window.ccAttachValidation = createValidator;

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function () { attachAll(); });
    } else {
        attachAll();
    }

    /* Forms injected later (a plugin, or an AJAX-swapped fragment) are picked
       up without anyone having to remember to call us. */
    if (window.MutationObserver) {
        new MutationObserver(function (records) {
            for (var i = 0; i < records.length; i++) {
                var added = records[i].addedNodes;
                for (var j = 0; j < added.length; j++) {
                    var n = added[j];
                    if (n.nodeType !== 1) continue;
                    if (n.matches && n.matches('form[data-cc-validate]')) createValidator(n);
                    else attachAll(n);
                }
            }
        }).observe(document.documentElement, { childList: true, subtree: true });
    }
})();

/* ---- js/src/60-newsletter.js ---- */
/**
 * Atrium — newsletter signup box.
 *
 * HOUSE RULE: no ES6 template literals in this folder. See 00-boot.js.
 *
 * The captcha block is hidden until the email field is focused, so an unused
 * footer widget never loads third-party captcha JS on every page view. Once
 * revealed it stays revealed — re-hiding it would tear down a widget the
 * customer may already have solved.
 */

document.addEventListener('alpine:init', function () {
    window.Alpine.data('ccNewsletter', function () {
        return {
            showCaptcha: false
        };
    });
});

/* ---- js/src/90-compat.js ---- */
/**
 * Atrium — behaviour shims for markup emitted by MODULES.
 *
 * HOUSE RULE: no ES6 template literals in this folder. See 00-boot.js.
 *
 * The CSS counterpart is css/src/compat.css. This file is for the cases CSS
 * cannot reach: module markup that depended on a Foundation JS behaviour the
 * reference skin provided and Atrium does not.
 *
 * Deliberately implemented as DELEGATED listeners on document, so they work on
 * markup that arrives after load (gateway forms are fetched into the checkout,
 * and the mini-basket is replaced wholesale by _g=ajaxadd).
 */

(function () {
    'use strict';

    /**
     * `.colorbox` — an inline image lightbox.
     *
     * modules/gateway/Card_Capture/skin/form.tpl emits, next to the CVV field:
     *     <a href="images/general/cvv.gif" class="colorbox">What's this?</a>
     * The reference skin rewrote that into a modal (2.cubecart.js:127-146).
     * Without a handler the link NAVIGATES AWAY from a part-completed card
     * form, mid-checkout, losing everything typed.
     *
     * Fixing it here rather than in a skin override of the module's template is
     * deliberate: an override forks the gateway's form permanently, so a future
     * module release that adds or renames a field would silently break payment
     * for Atrium stores only. The module keeps ownership of its markup; the
     * skin supplies the missing behaviour.
     */
    document.addEventListener('click', function (e) {
        var link = e.target.closest ? e.target.closest('a.colorbox') : null;
        if (!link) return;

        var href = link.getAttribute('href');
        if (!href) return;

        e.preventDefault();

        var overlay = document.createElement('div');
        overlay.className = 'cc-colorbox fixed inset-0 z-50 flex items-center justify-center bg-ink-950/80 p-4';
        overlay.setAttribute('role', 'dialog');
        overlay.setAttribute('aria-modal', 'true');
        overlay.setAttribute('aria-label', link.getAttribute('title') || link.textContent || '');

        var img = document.createElement('img');
        img.src = href;
        img.alt = link.getAttribute('title') || '';
        img.className = 'max-h-full max-w-full rounded-cc bg-white object-contain p-2';
        overlay.appendChild(img);

        function close() {
            overlay.remove();
            document.removeEventListener('keydown', onKey);
            if (link.focus) link.focus();          // return focus where it came from
        }
        function onKey(ev) { if (ev.key === 'Escape') close(); }

        overlay.addEventListener('click', close);
        document.addEventListener('keydown', onKey);
        document.body.appendChild(overlay);
    });
})();
